<?php
namespace App\Support;
use App\Models\{User,Apprentice,TrainingSession,AttendanceMark,RegisterFollowupCase as CaseRecord};
use Illuminate\Support\Facades\{DB,Crypt};
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
class RegisterActions {
 private static function fail(string $m='Register source, access or follow-up changed. Reload before saving.'):never {throw ValidationException::withMessages(['register_action'=>$m]);}
 public static function allowed(User $u,TrainingSession $s):bool {if(LearningAccess::manager($u)){return true;}if(!$u->active||$u->role!=='tutor'||$s->group?->tutor_id!==$u->id){return false;}$r=RegisterFollowup::roster($s);return $r['shape']&&!$r['duplicates']&&count($r['ids'])>0&&Apprentice::whereIn('id',$r['ids'])->count()===count($r['ids'])&&Apprentice::whereIn('id',$r['ids'])->where(fn($q)=>$q->whereNull('tutor_id')->orWhere('tutor_id','!=',$u->id))->doesntExist();}
 public static function caseAllowed(User $u,CaseRecord $c,TrainingSession $s):bool {if(LearningAccess::manager($u)){return true;}try{$ids=$c->details['scope_ids'];return self::intact($c)&&self::allowed($u,$s)&&count($ids)>0&&Apprentice::whereIn('id',$ids)->where('tutor_id',$u->id)->count()===count($ids);}catch(\Throwable){return false;}}
 public static function check(TrainingSession $s):array {$s=TrainingSession::with(['group','marks'])->findOrFail($s->id);$ready=RegisterFollowup::readiness($s);$roster=RegisterFollowup::roster($s);$people=Apprentice::whereIn('id',$roster['ids'])->orderBy('id')->get();$teacher=$s->group?->tutor_id?User::find($s->group->tutor_id):null;return ['readiness'=>$ready,'flag'=>in_array($ready['bucket'],['needs-register','checks'],true),'clear'=>in_array($ready['bucket'],['recorded','cancelled'],true),'hash'=>ReviewedImports::hash(['rules'=>'register-actions-v1','session'=>$s->getAttributes(),'group'=>$s->group?->getAttributes(),'teacher'=>$teacher?StaffHandover::staffSeal($teacher):null,'marks'=>$s->marks->sortBy('id')->map(fn($m)=>$m->getAttributes())->values()->all(),'profiles'=>$people->map(fn($a)=>['id'=>$a->id,'hash'=>ReviewedImports::hash($a->getAttributes())])->all()])];}
 public static function intact(CaseRecord $c):bool {try{return ReviewedImports::hash($c->details)===$c->details_hash&&$c->details['session_id']===$c->training_session_id&&$c->details['owner_id']===$c->owner_id&&$c->details['due_on']===$c->due_on->format('Y-m-d');}catch(\Throwable){return false;}}
 public static function position(CaseRecord $c,TrainingSession $s,?array $check=null):array {$check??=self::check($s);$verified=false;try{$p=$c->proof;$verified=self::intact($c)&&$p&&$p['state']===$c->state&&$p['version']===$c->version&&$p['details_hash']===$c->details_hash&&$p['source_hash']===$check['hash']&&$p['source_hash']===$c->source_hash&&$p['by']===$c->decided_by&&$c->decided_at&&$p['at']===$c->decided_at->toIso8601String();}catch(\Throwable){}$owner=User::find($c->owner_id);$ownerOk=$owner&&self::allowed($owner,$s);$resolved=$verified&&$c->state==='Resolved'&&$check['clear'];$deferred=$verified&&$ownerOk&&$c->state==='Deferred'&&$check['flag'];$withdrawn=$verified&&$c->state==='Withdrawn';$label=!self::intact($c)?'Evidence needs checking':($resolved?($check['readiness']['bucket']==='cancelled'?'Resolved: session cancelled, no register inferred':'Resolved against current register'):($withdrawn?'Withdrawn; register flags remain independent':(!$ownerOk?'Owner access needs reassignment':($deferred?'Deferred; register flag remains':($c->state==='Open'?'Open':'Source changed / needs recheck')))));return ['label'=>$label,'resolved'=>$resolved,'deferred'=>$deferred,'withdrawn'=>$withdrawn,'overdue'=>!$resolved&&!$withdrawn&&$c->due_on->lt(today()),'owner_current'=>(bool)$ownerOk,'source_hash'=>$check['hash']];}
 private static function actor(User $u,int $auth,TrainingSession $s):User {$u=User::whereKey($u->id)->lockForUpdate()->firstOrFail();abort_unless($u->auth_version===$auth&&self::allowed($u,$s),403);return $u;}
 private static function event(CaseRecord $c,User $u,string $event,array $data=[]):void {DB::table('register_followup_events')->insert(['case_id'=>$c->id,'actor_id'=>$u->id,'event'=>$event,'payload'=>Crypt::encryptString(json_encode($data,JSON_THROW_ON_ERROR)),'created_at'=>now()]);}
 public static function save(User $actor,int $auth,TrainingSession $session,?CaseRecord $record,int $version,string $hash,array $data):CaseRecord {
  return DB::transaction(function()use($actor,$auth,$session,$record,$version,$hash,$data):CaseRecord {$s=TrainingSession::whereKey($session->id)->lockForUpdate()->firstOrFail();$u=self::actor($actor,$auth,$s);$c=$record?CaseRecord::whereKey($record->id)->lockForUpdate()->firstOrFail():null;if($c){abort_unless(self::caseAllowed($u,$c,$s),403);}if(($c&&($c->training_session_id!==$s->id||!self::intact($c)))||($c?->version??0)!==$version||(!$c&&CaseRecord::where('training_session_id',$s->id)->exists())){self::fail();}$check=self::check($s);if(!hash_equals($check['hash'],$hash)||(!$c&&!$check['flag'])){self::fail('Use a current missing-register/source-check flag.');}$owner=User::whereKey($data['owner_id'])->lockForUpdate()->first();if(!$owner||!self::allowed($owner,$s)){self::fail('Choose an active manager or tutor with current full register scope.');}$before=$c?['details'=>$c->details,'state'=>$c->state,'proof'=>$c->proof]:null;$c??=new CaseRecord(['training_session_id'=>$s->id,'created_by'=>$u->id]);if(!$c->id){$c->id=(string)Str::uuid();}$d=['session_id'=>$s->id,'owner_id'=>$owner->id,'due_on'=>$data['due_on'],'scope_ids'=>RegisterFollowup::roster($s)['ids'],'note'=>$data['note']];$c->details=$d;$c->details_hash=ReviewedImports::hash($d);$c->owner_id=$owner->id;$c->due_on=$data['due_on'];$c->state='Open';$c->version=$version+1;$c->source_hash=$hash;$c->proof=null;$c->decided_by=null;$c->decided_at=null;$c->save();self::event($c,$u,'case_saved',['before'=>$before,'after'=>$d]);return $c;},3);
 }
 public static function decide(User $actor,int $auth,CaseRecord $record,int $version,string $hash,string $decision,string $note):void {
  DB::transaction(function()use($actor,$auth,$record,$version,$hash,$decision,$note):void {$s=TrainingSession::whereKey($record->training_session_id)->lockForUpdate()->firstOrFail();$u=self::actor($actor,$auth,$s);$c=CaseRecord::whereKey($record->id)->lockForUpdate()->firstOrFail();abort_unless(self::caseAllowed($u,$c,$s),403);$check=self::check($s);if(!self::intact($c)||$c->version!==$version||!hash_equals($hash,$check['hash'])||!in_array($decision,['resolve','defer','reopen','withdraw'],true)){self::fail();}if($decision==='resolve'&&!$check['clear']){self::fail('Resolve only after the actual register is recorded or the session is explicitly cancelled.');}if($decision==='defer'&&(!$check['flag']||$c->due_on->lt(today())||!($owner=User::find($c->owner_id))||!self::allowed($owner,$s))){self::fail('Deferral needs a current flag, future/current review date and eligible owner; it never fills attendance.');}$before=['state'=>$c->state,'proof'=>$c->proof,'source_hash'=>$c->source_hash];$c->state=['resolve'=>'Resolved','defer'=>'Deferred','reopen'=>'Open','withdraw'=>'Withdrawn'][$decision];$c->version++;$c->source_hash=$hash;$c->decided_by=$u->id;$c->decided_at=now()->setMicrosecond(0);$c->proof=$decision==='reopen'?null:['state'=>$c->state,'version'=>$c->version,'details_hash'=>$c->details_hash,'source_hash'=>$hash,'by'=>$u->id,'at'=>$c->decided_at->toIso8601String(),'register_bucket'=>$check['readiness']['bucket'],'note'=>$note];$c->save();self::event($c,$u,'case_'.$decision,['before'=>$before,'note'=>$note]);},3);
 }
}
